-- Analytics fact fixture (test only).
--
-- Production table names, bounded column shapes and the CHECK constraints the
-- exercise relies on. Loaded by contract-test schemas only; never applied to a
-- deployed database. These tables are read-only for the runtime role.

CREATE TABLE organizations (
    id uuid PRIMARY KEY,
    name text NOT NULL,
    type text NOT NULL DEFAULT 'FUEL_BUYER',
    provenance text NOT NULL DEFAULT 'UNKNOWN',
    created_at timestamptz NOT NULL,
    CONSTRAINT ck_organizations_provenance CHECK (provenance IN ('REAL', 'DEMO', 'UNKNOWN'))
);

CREATE TABLE users (
    id uuid PRIMARY KEY,
    email text NOT NULL,
    password_hash text NOT NULL,
    role text,
    status text NOT NULL DEFAULT 'PENDING',
    organization_id uuid REFERENCES organizations(id),
    last_login timestamptz,
    created_at timestamptz NOT NULL,
    email_verified boolean NOT NULL DEFAULT false
);

CREATE TABLE orderbook_orders (
    id uuid PRIMARY KEY,
    organization_id uuid NOT NULL REFERENCES organizations(id),
    side text NOT NULL,
    status text NOT NULL,
    provenance text NOT NULL DEFAULT 'UNKNOWN',
    created_at timestamptz NOT NULL,
    expires_at timestamptz,
    remaining_quantity_mt numeric(18, 2) NOT NULL,
    product_id uuid,
    delivery_point_id uuid,
    availability_window text,
    CONSTRAINT ck_orderbook_side CHECK (side IN ('BID', 'ASK')),
    CONSTRAINT ck_orderbook_remaining CHECK (remaining_quantity_mt >= 0)
);

CREATE TABLE trades (
    id uuid PRIMARY KEY,
    bid_order_id uuid REFERENCES orderbook_orders(id),
    ask_order_id uuid REFERENCES orderbook_orders(id),
    buyer_id uuid NOT NULL REFERENCES organizations(id),
    seller_id uuid NOT NULL REFERENCES organizations(id),
    buyer_provenance text NOT NULL DEFAULT 'UNKNOWN',
    seller_provenance text NOT NULL DEFAULT 'UNKNOWN',
    status text NOT NULL,
    created_at timestamptz NOT NULL,
    confirmed_at timestamptz,
    paid_at timestamptz,
    quantity_mt numeric(18, 2) NOT NULL,
    final_quantity_mt numeric(18, 2),
    final_total_usd numeric(18, 2)
);

CREATE TABLE user_login_days (
    id uuid PRIMARY KEY,
    activity_date date NOT NULL,
    user_id uuid NOT NULL REFERENCES users(id),
    organization_id uuid,
    role text,
    login_count integer NOT NULL DEFAULT 1,
    first_login_at timestamptz NOT NULL,
    last_login_at timestamptz NOT NULL,
    CONSTRAINT uq_user_login_days_date_user UNIQUE (activity_date, user_id)
);

CREATE TABLE user_status_transitions (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id),
    organization_id uuid,
    role text,
    from_status text,
    to_status text NOT NULL,
    effective_at timestamptz NOT NULL,
    provenance text NOT NULL DEFAULT 'workflow'
);

